CREATE VIEW "public"."sales_by_site" AS (select "daily_transaction_lines"."project_id", "daily_transaction_lines"."location_id", "daily_transaction_lines"."category_key", max("daily_transaction_lines"."label") as "label", coalesce(sum("daily_transaction_lines"."amount"), 0) as "amount" from "daily_transaction_lines" inner join "daily_transactions" on ("daily_transaction_lines"."transaction_id" = "daily_transactions"."id" and "daily_transactions"."kind" = 'sales') group by "daily_transaction_lines"."project_id", "daily_transaction_lines"."location_id", "daily_transaction_lines"."category_key");